import{_ as t,o,c as e,ak as r}from"./chunks/framework.B8Q0aS9d.js";const p=JSON.parse('{"title":"Инженер по охране труда и технике безопасности (ОТ и ТБ)","description":"","frontmatter":{},"headers":[],"relativePath":"data/ai-construction-part7.md","filePath":"data/ai-construction-part7.md"}'),i={name:"data/ai-construction-part7.md"};function l(n,a,s,c,d,h){return o(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="инженер-по-охране-труда-и-технике-безопасности-от-и-тб" tabindex="-1">Инженер по охране труда и технике безопасности (ОТ и ТБ) <a class="header-anchor" href="#инженер-по-охране-труда-и-технике-безопасности-от-и-тб" aria-label="Permalink to &quot;Инженер по охране труда и технике безопасности (ОТ и ТБ)&quot;">​</a></h1><p>В эпоху цифровой трансформации обеспечение безопасности на строительной площадке переходит от бумажных журналов к проактивному цифровому контролю. Искусственный интеллект и технологии компьютерного зрения позволяют предотвращать несчастные случаи до того, как они произойдут, превращая систему ОТ и ТБ из карательного органа в умный цифровой щит.</p><div class="info custom-block"><p class="custom-block-title">Роль и задачи в современности</p><p>Инженер по ОТ и ТБ внедряет передовые системы компьютерного зрения и машинного обучения для непрерывного автоматического мониторинга строительной площадки и предотвращения несчастных случаев.</p></div><h2 id="рекомендуемые-ии-инструменты" tabindex="-1">Рекомендуемые ИИ-инструменты <a class="header-anchor" href="#рекомендуемые-ии-инструменты" aria-label="Permalink to &quot;Рекомендуемые ИИ-инструменты&quot;">​</a></h2><p>Для автоматического контроля за ситуацией на площадке и предиктивного анализа рисков травматизма применяется следующий ИИ-стек:</p><ul><li><strong>Voxel / Viisights</strong> — мощные ИИ-платформы для интеграции с существующими камерами видеонаблюдения, способные распознавать опасное поведение людей в реальном времени.</li><li><strong>Newmetrix (от Smartvid.io)</strong> — специализированная нейросеть для прогнозирования рисков производственного травматизма на основе регулярных фото- и видеоотчетов.</li><li><strong>ChatGPT</strong> — текстовая языковая модель для оперативной генерации кастомных инструктажей, планов локализации аварий и глубокого анализа корневых причин произошедших инцидентов.</li></ul><hr><h2 id="в-чем-конкретно-помогает-ии" tabindex="-1">В чем конкретно помогает ИИ <a class="header-anchor" href="#в-чем-конкретно-помогает-ии" aria-label="Permalink to &quot;В чем конкретно помогает ИИ&quot;">​</a></h2><p>Использование алгоритмов искусственного интеллекта на стройке позволяет вести круглосуточный надзор за безопасностью без привлечения огромного штата контролеров:</p><ol><li><strong>Контроль СИЗ</strong> Умные камеры автоматически фиксируют сотрудников без касок, сигнальных жилетов или страховочных привязей и мгновенно отправляют уведомление прорабу.</li><li><strong>Мониторинг опасных зон</strong> Система моментально распознает нахождение людей в опасной близости от работающего крана, строительной техники или у неогражденного края технологических проемов.</li><li><strong>Предиктивная аналитика</strong> Оценивает общий уровень рисков на площадке (например, фиксируя общую захламленность проходов или плохую освещенность) и заранее предупреждает о высокой вероятности ЧП.</li></ol><hr><h2 id="практические-промты-для-работы" tabindex="-1">Практические промты для работы <a class="header-anchor" href="#практические-промты-для-работы" aria-label="Permalink to &quot;Практические промты для работы&quot;">​</a></h2><p>Вы можете использовать эти проверенные шаблоны запросов для автоматизации инженерных задач и работы с документацией.</p><h3 id="_1-промт-для-создания-точечного-инструктажа" tabindex="-1">1. Промт для создания точечного инструктажа <a class="header-anchor" href="#_1-промт-для-создания-точечного-инструктажа" aria-label="Permalink to &quot;1. Промт для создания точечного инструктажа&quot;">​</a></h3><blockquote><p><code>«Напиши краткий, емкий и жесткий 5-минутный инструктаж (toolbox talk) для рабочих, которые сегодня будут выполнять сварочные работы на высоте 10 метров в условиях сильного ветра (до 12 м/с). Выдели 3 главных правила выживания».</code></p></blockquote><h3 id="_2-промт-для-анализа-инцидента-метод-5-почему" tabindex="-1">2. Промт для анализа инцидента (метод &quot;5 Почему&quot;) <a class="header-anchor" href="#_2-промт-для-анализа-инцидента-метод-5-почему" aria-label="Permalink to &quot;2. Промт для анализа инцидента (метод &quot;5 Почему&quot;)&quot;">​</a></h3><blockquote><p><code>«Проведи анализ происшествия методом &quot;5 Почему&quot;. Описание: Рабочий упал со стремянки высотой 1.5 метра и повредил ногу. Стремянка была исправна, но стояла на неровном строительном мусоре. Рабочий спешил закончить прокладку кабеля до конца смены. Найди корневую причину и предложи системное решение».</code></p></blockquote>',17)])])}const _=t(i,[["render",l]]);export{p as __pageData,_ as default};
